// Good code: Properly sanitizing and escaping user input to prevent XSS
public class SafeExample {
    public static void main(String[] args) {
        String userInput = "<script>alert('XSS');</script>";
        try {
            // Decoding user input first
            String decodedInput = java.net.URLDecoder.decode(userInput, "UTF-8");
            // Sanitizing input to prevent XSS by escaping HTML characters
            String sanitizedInput = sanitizeInput(decodedInput);
            System.out.println("Sanitized input: " + sanitizedInput);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Method to sanitize input by escaping HTML characters
    private static String sanitizeInput(String input) {
        if (input == null) {
            return "";
        }
        return input.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
    }
}
